/**
 * Builds the map from the old TypeDoc site (chmuzamil.github.io/pakdatakit/,
 * TypeDoc's HTML theme) to the new API reference pages on pakdatakit.dev
 * (/api/typescript/..., generated by starlight-typedoc), and writes it to
 * site/api-redirects.json. The GitHub Pages stub (scripts/docs-stub.mjs) and
 * the Nginx redirects use this file.
 *
 * The old URLs come from TypeDoc's own output: the root typedoc.json is
 * rendered to a temporary folder, exactly as docs.yml used to publish it.
 *
 *   node scripts/api-redirects.mjs          write site/api-redirects.json
 *   node scripts/api-redirects.mjs --check  after `npm run build`: fail if the
 *     committed file is stale, if a target page does not exist in dist/, or if
 *     an API page (function, type, interface, variable, module) has no page of
 *     its own on the new site and had to fall back to its module page.
 */
import { execFileSync } from 'node:child_process';
import { existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const site = fileURLToPath(new URL('..', import.meta.url));
const root = join(site, '..');
const dist = join(site, 'dist');
const out = join(site, 'api-redirects.json');
const check = process.argv.includes('--check');

const API = '/api/typescript/';
/** TypeDoc HTML folder → starlight-typedoc folder. */
const KIND = {
  functions: 'functions',
  interfaces: 'interfaces',
  types: 'type-aliases',
  variables: 'variables',
  classes: 'classes',
  enums: 'enumerations',
};
/** Pages that are not API reflections, with the closest new page. */
const FIXED = {
  'index.html': API,
  'modules.html': API,
  'hierarchy.html': API,
  'documents/DATA.html': '/data/',
  'documents/CHANGELOG.html': '/releases/',
};

// ---- Old URLs: render the old site with TypeDoc's HTML theme.
const tmp = mkdtempSync(join(tmpdir(), 'pdk-old-api-'));
let oldPages;
try {
  execFileSync(process.platform === 'win32' ? 'npx.cmd' : 'npx', ['typedoc', '--out', tmp, '--logLevel', 'Error'], {
    cwd: root,
    stdio: ['ignore', 'ignore', 'inherit'],
    shell: process.platform === 'win32',
  });
  const walk = (dir) =>
    readdirSync(dir).flatMap((n) => {
      const p = join(dir, n);
      return statSync(p).isDirectory() ? walk(p) : n.endsWith('.html') ? [relative(tmp, p).replace(/\\/g, '/')] : [];
    });
  oldPages = walk(tmp).sort();
} finally {
  rmSync(tmp, { recursive: true, force: true });
}
if (oldPages.length < 100) throw new Error(`api-redirects: TypeDoc produced only ${oldPages.length} pages`);

// ---- The new pages: starlight-typedoc's generated content (written by `astro build`).
const content = join(site, 'src', 'content', 'docs', 'api', 'typescript');
if (!existsSync(content)) throw new Error('api-redirects: run `npm run build` in site/ first (no generated API pages)');
const newPages = new Set(
  (function walk(dir) {
    return readdirSync(dir).flatMap((n) => {
      const p = join(dir, n);
      if (statSync(p).isDirectory()) return walk(p);
      const rel = relative(content, p).replace(/\\/g, '/').replace(/\.mdx?$/, '').toLowerCase(); // Starlight lowercases slugs
      return [API + (rel === 'index' ? '' : rel.replace(/(^|\/)index$/, '') + '/')];
    });
  })(content),
);

// ---- Map every old page.
const redirects = {};
const fallbacks = [];
for (const page of oldPages) {
  if (FIXED[page]) {
    redirects[page] = FIXED[page];
    continue;
  }
  const [dir, file] = page.split('/');
  const name = file?.replace(/\.html$/, '');
  if (dir === 'modules' && name) {
    const target = `${API}${name.replace(/_/g, '/')}/`;
    if (newPages.has(target)) redirects[page] = target;
    else fallbacks.push(page), (redirects[page] = API);
    continue;
  }
  if (KIND[dir] && name) {
    // "<module>.<Name>", the module using _ for /, e.g. adapters_zod.AdapterOptions
    const dot = name.lastIndexOf('.');
    const mod = name.slice(0, dot).replace(/_/g, '/');
    const target = `${API}${mod}/${KIND[dir]}/${name.slice(dot + 1).toLowerCase()}/`;
    if (newPages.has(target)) redirects[page] = target;
    else {
      fallbacks.push(page);
      redirects[page] = newPages.has(`${API}${mod}/`) ? `${API}${mod}/` : API;
    }
    continue;
  }
  // Anything else (e.g. documents/SECURITY.html): the reference's front page.
  redirects[page] = API;
}

const json = `${JSON.stringify(redirects, null, 2)}\n`;

if (!check) {
  writeFileSync(out, json);
  console.log(`api-redirects: ${oldPages.length} old pages mapped (${fallbacks.length} fell back) → ${relative(root, out)}`);
  if (fallbacks.length) console.log(`  fell back: ${fallbacks.join(', ')}`);
  process.exit(0);
}

// ---- --check
const problems = [];
if (!existsSync(out) || readFileSync(out, 'utf8') !== json)
  problems.push('site/api-redirects.json is stale: run `node scripts/api-redirects.mjs` in site/ and commit it');
for (const page of fallbacks) problems.push(`no new page for ${page} (fell back to ${redirects[page]})`);
for (const [from, to] of Object.entries(redirects)) {
  if (!existsSync(join(dist, to, 'index.html'))) problems.push(`${from} → ${to}: no such page in dist/`);
}
if (problems.length) {
  console.error(`api-redirects: ${problems.length} problem(s):\n  ${problems.slice(0, 30).join('\n  ')}`);
  process.exit(1);
}
console.log(`api-redirects: all ${oldPages.length} old URLs map to pages that exist`);
